const API_URL = process.env.NEXT_PUBLIC_API_URL;

export async function fetchBranches(searchQuery = '', cityId = '') {
  try {
    const res = await fetch(`${API_URL}/branches?search=${searchQuery}&city_id=${cityId}`, {
      cache: 'no-store'
    });
    const data = await res.json();
    return data.branches?.data || [];
  } catch (err) {
    console.error('Failed to fetch branches', err);
    return [];
  }
}

export async function fetchCities() {
  try {
    const res = await fetch(`${API_URL}/cities`, { cache: 'no-store' });
    const data = await res.json();
    return data.cities || [];
  } catch (err) {
    console.error('Failed to fetch cities', err);
    return [];
  }
}

export async function registerRestaurant(formData) {
  try {
    const res = await fetch(`${API_URL}/restaurants/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(formData),
    });
    return await res.json();
  } catch (err) {
    console.error('Restaurant registration failed', err);
    return { status: false, message: 'Network or server error' };
  }
}

export async function loginUser(credentials) {
  try {
    const res = await fetch(`${API_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(credentials),
    });
    return await res.json();
  } catch (err) {
    console.error('Login failed', err);
    return { status: false, message: 'Network or server error' };
  }
}